"""d_max sensitivity analysis for Toda-Yamamoto Granger causality.

Tests whether the TY spurious-rate conclusion (75% under adaptive d_max)
is robust to the choice of d_max by comparing three settings:
  d_max=0: assume stationarity, TY degrades to standard Granger (most power)
  d_max=adaptive: ADF-driven per-series integration order (baseline)
  d_max=1: assume at most I(1), always add 1 extra lag (most conservative)

Input:  results/mvp/rep_{seed}/all_metrics.json (seeds 42-45)
Output: results/mvp/analysis/method_ablation_dmax_sensitivity.json
"""

import json
import os
import warnings
from itertools import product

import numpy as np
from scipy import stats
from statsmodels.tsa.stattools import adfuller

warnings.filterwarnings("ignore")

CANARY = ["token_entropy", "self_bleu", "ece", "effective_rank"]
DOWNSTREAM = ["perplexity", "distinct_1", "distinct_2", "distinct_3"]
HIGHER_IS_WORSE = {"self_bleu", "ece", "perplexity"}
LOWER_IS_WORSE = {"token_entropy", "effective_rank",
                   "distinct_1", "distinct_2", "distinct_3"}
ALPHA = 0.05
SEEDS = [42, 43, 44, 45]
DATA_DIR = "results/mvp"


def load_metrics(data_dir, seeds):
    data = {}
    for s in seeds:
        path = os.path.join(data_dir, f"rep_{s}", "all_metrics.json")
        with open(path) as f:
            data[s] = json.load(f)
    return data


def extract(metrics_list, name):
    return np.array([m[name] for m in sorted(metrics_list,
                                              key=lambda x: x["generation"])])


def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()


def adf_order(series, max_d=2):
    """Integration order via iterated ADF (maxlag=1 for short series)."""
    for d in range(max_d + 1):
        s = series.copy()
        for _ in range(d):
            s = np.diff(s)
        if len(s) < 5:
            return d
        try:
            if adfuller(s, maxlag=1, autolag=None)[1] < 0.05:
                return d
        except Exception:
            pass
    return max_d


def ty_test(x, y, d_max_override=None, dc=None, dd=None):
    """Run TY Granger causality with a specific or adaptive d_max.

    Args:
        x: canary series (already oriented)
        y: downstream series (already oriented)
        d_max_override: if int, use this d_max directly;
                        if None, use adaptive (max of ADF orders)
        dc, dd: pre-computed integration orders (for reporting only)
    """
    n = len(x)

    if dc is None:
        dc = adf_order(x)
    if dd is None:
        dd = adf_order(y)

    if d_max_override is not None:
        d_max = d_max_override
    else:
        d_max = max(dc, dd)

    # p=1 always: T=11 only supports 1 autoregressive lag
    p = 1
    k = p + d_max
    T_eff = n - k
    n_params = 1 + 2 * k
    df_resid = T_eff - n_params

    if df_resid < 1:
        return {
            "wald_F": None, "p_value": None, "significant": False,
            "df_resid": df_resid, "d_max": int(d_max), "k": int(k),
            "d_canary": int(dc), "d_downstream": int(dd),
            "note": f"no residual df (T_eff={T_eff}, params={n_params})",
        }

    Y = y[k:]
    X_cols = [np.ones(T_eff)]
    for l in range(1, k + 1):
        X_cols.append(x[k - l : n - l])
        X_cols.append(y[k - l : n - l])
    X = np.column_stack(X_cols)

    try:
        beta = np.linalg.lstsq(X, Y, rcond=None)[0]
        resid = Y - X @ beta
        sigma2 = np.sum(resid ** 2) / df_resid
        XtX_inv = np.linalg.inv(X.T @ X)
    except Exception:
        return {
            "wald_F": None, "p_value": None, "significant": False,
            "df_resid": int(df_resid), "d_max": int(d_max), "k": int(k),
            "d_canary": int(dc), "d_downstream": int(dd),
            "note": "OLS failed",
        }

    # Wald test on first p canary-lag coefficients
    test_idx = [2 * (l - 1) + 1 for l in range(1, p + 1)]
    R = np.zeros((p, n_params))
    for i, idx in enumerate(test_idx):
        R[i, idx] = 1.0

    Rb = R @ beta
    try:
        cov_Rb = sigma2 * (R @ XtX_inv @ R.T)
        W = float(Rb @ np.linalg.inv(cov_Rb) @ Rb)
        F = W / p
        pval = float(1.0 - stats.f.cdf(F, p, df_resid))
    except Exception:
        return {
            "wald_F": None, "p_value": None, "significant": False,
            "df_resid": int(df_resid), "d_max": int(d_max), "k": int(k),
            "d_canary": int(dc), "d_downstream": int(dd),
            "note": "Wald failed",
        }

    return {
        "wald_F": round(float(F), 4),
        "p_value": round(float(pval), 6),
        "significant": bool(pval < ALPHA),
        "df_resid": int(df_resid),
        "d_max": int(d_max),
        "k": int(k),
        "d_canary": int(dc),
        "d_downstream": int(dd),
    }


def main():
    os.chdir("/root/autodl-tmp/distrib_canary_collapse")
    data = load_metrics(DATA_DIR, SEEDS)

    # Three d_max settings:
    #   0 = stationarity assumed → standard Granger (highest power, strongest assumption)
    #   None = adaptive via ADF (baseline from method_ablation)
    #   1 = assume at most I(1) (most conservative, uniform df_resid=4)
    dmax_settings = {"d_max_0": 0, "d_max_adaptive": None, "d_max_1": 1}

    results = {}
    for setting_name, dmax_val in dmax_settings.items():
        results[setting_name] = {}
        for cn, dn in product(CANARY, DOWNSTREAM):
            pair_key = f"{cn}_to_{dn}"
            pair_results = {}
            for seed in SEEDS:
                c_arr = extract(data[seed], cn)
                d_arr = extract(data[seed], dn)
                x, y = orient(c_arr, cn), orient(d_arr, dn)
                dc, dd = adf_order(x), adf_order(y)
                r = ty_test(x, y, d_max_override=dmax_val, dc=dc, dd=dd)
                pair_results[f"seed_{seed}"] = {
                    "F": r["wald_F"],
                    "p": r["p_value"],
                    "df_resid": r["df_resid"],
                    "verdict": "SIGNIFICANT" if r["significant"] else "NOT_SIGNIFICANT",
                    "d_max_used": r["d_max"],
                    "d_canary": r["d_canary"],
                    "d_downstream": r["d_downstream"],
                }
            results[setting_name][pair_key] = pair_results

    # --- Compute summaries ---
    # Majority-vote verdict per pair per setting
    def majority_verdict(pair_dict):
        n_sig = sum(1 for v in pair_dict.values() if v["verdict"] == "SIGNIFICANT")
        return "SIGNIFICANT" if n_sig > len(SEEDS) / 2 else "NOT_SIGNIFICANT"

    # Spurious rate: (naive SIG ∩ TY not SIG) / naive SIG
    # All 16 pairs are naive-significant per method_ablation
    n_naive = 16
    spurious_rates = {}
    pair_verdicts = {}

    for setting_name in dmax_settings:
        n_ty_not_sig = 0
        for pair_key in results[setting_name]:
            v = majority_verdict(results[setting_name][pair_key])
            pair_verdicts.setdefault(pair_key, {})[setting_name] = v
            if v == "NOT_SIGNIFICANT":
                n_ty_not_sig += 1
        spurious_rates[setting_name] = round(n_ty_not_sig / n_naive, 4)

    # ECE special analysis
    ece_pairs = ["ece_to_distinct_2", "ece_to_distinct_3"]
    ece_analysis = {}
    for pair_key in ece_pairs:
        ece_analysis[pair_key] = {}
        for setting_name in dmax_settings:
            seeds_data = results[setting_name][pair_key]
            verdict = majority_verdict(seeds_data)
            per_seed = {sk: {"F": sv["F"], "p": sv["p"], "verdict": sv["verdict"]}
                        for sk, sv in seeds_data.items()}
            ece_analysis[pair_key][setting_name] = {
                "majority_verdict": verdict,
                "per_seed": per_seed,
            }
        # Flip detection: adaptive is NOT_SIGNIFICANT, does 0 or 1 flip to SIGNIFICANT?
        adaptive_v = ece_analysis[pair_key]["d_max_adaptive"]["majority_verdict"]
        ece_analysis[pair_key]["flips"] = {
            sn: ece_analysis[pair_key][sn]["majority_verdict"] != adaptive_v
            for sn in dmax_settings
        }

    # token_entropy→perplexity special analysis
    te_ppl_key = "token_entropy_to_perplexity"
    te_ppl_analysis = {}
    for setting_name in dmax_settings:
        seeds_data = results[setting_name][te_ppl_key]
        te_ppl_analysis[setting_name] = {
            sk: {"F": sv["F"], "p": sv["p"], "verdict": sv["verdict"]}
            for sk, sv in seeds_data.items()
        }
        te_ppl_analysis[setting_name]["majority_verdict"] = majority_verdict(seeds_data)

    # Pair-level verdict table
    verdict_table = {}
    for pair_key in results["d_max_0"]:
        verdict_table[pair_key] = {
            sn: pair_verdicts[pair_key][sn] for sn in dmax_settings
        }

    results["summary"] = {
        "spurious_rates": spurious_rates,
        "verdict_table": verdict_table,
        "ece_distinct2_analysis": ece_analysis.get("ece_to_distinct_2", {}),
        "ece_distinct3_analysis": ece_analysis.get("ece_to_distinct_3", {}),
        "token_entropy_perplexity_analysis": te_ppl_analysis,
    }

    # Save
    out_dir = os.path.join(DATA_DIR, "analysis")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "method_ablation_dmax_sensitivity.json")
    with open(out_path, "w") as f:
        json.dump(results, f, indent=2)
    print(f"Saved: {out_path}")

    # --- Console report ---
    print()
    print("=" * 72)
    print("d_max SENSITIVITY ANALYSIS — Toda-Yamamoto Granger Causality")
    print("=" * 72)

    print("\n1. SPURIOUS RATES")
    print("-" * 40)
    for sn, sr in spurious_rates.items():
        print(f"  {sn:<16}: {sr:.0%} ({int(sr * n_naive)}/{n_naive})")

    print("\n2. PAIR-LEVEL VERDICT TABLE")
    print(f"  {'Pair':<35} {'d_max=0':>10} {'adaptive':>10} {'d_max=1':>10}")
    print("  " + "-" * 65)
    for pair_key in sorted(verdict_table):
        v = verdict_table[pair_key]
        labels = []
        for sn in ["d_max_0", "d_max_adaptive", "d_max_1"]:
            labels.append("SIG" if v[sn] == "SIGNIFICANT" else "n.s.")
        cn, dn = pair_key.split("_to_")
        print(f"  {cn+'→'+dn:<35} {labels[0]:>10} {labels[1]:>10} {labels[2]:>10}")

    print("\n3. ECE CANARY STATUS SENSITIVITY")
    print("-" * 60)
    for pair_key in ece_pairs:
        ea = ece_analysis[pair_key]
        cn, dn = pair_key.split("_to_")
        print(f"\n  {cn} → {dn}:")
        for sn in dmax_settings:
            v = ea[sn]["majority_verdict"]
            flipped = " ← FLIPPED" if ea["flips"][sn] else ""
            p_vals = [ea[sn]["per_seed"][f"seed_{s}"]["p"] for s in SEEDS]
            p_str = ", ".join(f"{p:.4f}" if p is not None else "N/A" for p in p_vals)
            print(f"    {sn:<16}: {v:<17} p=[{p_str}]{flipped}")

    print("\n4. token_entropy → perplexity")
    print("-" * 60)
    for sn in dmax_settings:
        d = te_ppl_analysis[sn]
        v = d["majority_verdict"]
        p_vals = [d[f"seed_{s}"]["p"] for s in SEEDS]
        p_str = ", ".join(f"{p:.4f}" if p is not None else "N/A" for p in p_vals)
        print(f"  {sn:<16}: {v:<17} p=[{p_str}]")

    print()


if __name__ == "__main__":
    main()
